  * tools/gl_budget.py both get its result. */
-static int glshim_clamp_box(GLint x0, GLint y0, GLint x1, GLint y1, int w, int h,
+TGL_HOT static int glshim_clamp_box(GLint x0, GLint y0, GLint x1, GLint y1, int w, int h,
