   (void)drawable;
   if (!g_canvas) return;
+  if (g_scale == 2) {
+    double_into_canvas();
+    return;
+  }
   const Box boxes[2] = {g_swap_erased, g_swap_drawn};
   for (int i = 0; i < 2; i++)
     if (!box_empty(boxes[i]))
@@ -233,6 +288,9 @@ void glXSwapBuffers(Display *dpy, GLXDrawable drawable) {
                         boxes[i].x1 - boxes[i].x0 + 1,
                         boxes[i].y1 - boxes[i].y0 + 1);
   g_swap_drawn = g_swap_erased = kEmptyBox;
+#ifdef GL_PROFILE
+  glshim_prof_frames++;
+#endif
 }

 static int stride_in_bytes(int stride, int size) {
@@ -395,3 +453,10 @@ void gluLookAt(GLdouble eyex, GLdouble eyey, GLdouble eyez, GLdouble cx,
   glMultMatrixf(m);
   glTranslatef((GLfloat)-eyex, (GLfloat)-eyey, (GLfloat)-eyez);
 }
