TGL_HOT void gl_draw_triangle(GLVertex* p0, GLVertex* p1, GLVertex* p2) {
	GLPROF_SCOPE(GLPROF_TRIANGLE);
	GLContext* c = gl_get_context();
	GLint co, cc[3], front;

	cc[0] = p0->clip_code;
	cc[1] = p1->clip_code;
	cc[2] = p2->clip_code;

	co = cc[0] | cc[1] | cc[2];

	/* we handle the non clipped case here to go faster */
	if (co == 0) {
