extern "C" {
#endif

enum {
  GLPROF_CLEAR,
  GLPROF_LIST,
  GLPROF_VERTEX,
  GLPROF_SHADE,
  GLPROF_TRIANGLE,
  GLPROF_FILL,
  GLPROF_POINT,
  GLPROF_LINE,
  GLPROF_SLOTS
};

