+static void memBench(uint16_t *psram) {
+  uint32_t seq = memWalk(psram, 1, kSize * kSize / 16, 16);
+  uint32_t col = memWalk(psram, 32, kSize, kSize);
+  volatile uint16_t *b = psram;
